def fibonacci(n):
    if n < 0:
        raise ValueError("El índice debe ser un número entero no negativo.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# Ejemplo de uso
print(fibonacci(10))  # Devuelve 55
